INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("人助けが大好き！　前向き格闘娘", 100101, 8, 27, 2, 0, "トゥインクルウィッシュ", "ヒヨリ", "東山奈央", "A", 44, 155, "人助け、応援", 16, "獣人族", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("戦闘のサポートが得意な、心優しい少女", 100201, 4, 5, 2, 0, "トゥインクルウィッシュ", "ユイ", "種田梨沙", "O", 47, 158, "料理、人間観察", 17, "ヒューマン", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("クールで何事にも真っ直ぐな剣士", 100301, 1, 12, 2, 0, "トゥインクルウィッシュ", "レイ", "早見沙織", "B", 46, 163, "読書、乗馬、お茶", 18, "魔族", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("探検好きのイタズラっ子", 100401, 8, 10, 5, 0, "リトルリリカル", "ミソギ", "諸星すみれ", "O", 27, 128, "いたずら、探検", 9, "ヒューマン", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("ヒーローに憧れる騎士見習いの少女", 100501, 11, 25, 8, 0, "王宮騎士団（NIGHTMARE）", "マツリ", "下田麻美", "O", 40, 146, "ヒーローごっこ", 12, "獣人族", "？？？");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("甘え上手なみんなの人気者", 100601, 11, 22, 7, 0, "悪魔偽王国軍（ディアボロス）", "アカリ", "浅倉杏美", "O", 42, 150, "サックス", 13, "魔族", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("プリン大好きゴースト娘", 100701, 1, 23, 7, 0, "悪魔偽王国軍（ディアボロス）", "ミヤコ", "雨宮天", "B", 32, 130, "プリンを食べること", 14, "魔族", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("ボクは誰よりも美しい", 100801, 10, 10, 15, 0, "ヴァイスフリューゲル　ランドソル支部", "ユキ", "大空直美", "AB", 40, 150, "鏡で自分を見ること", 14, "エルフ", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("前世を信じる中二病患者、「疾風の冥姫」", 100901, 7, 5, 13, 0, "トワイライトキャラバン", "アンナ", "髙野麻美", "A", 45, 159, "小説執筆", 17, "魔族", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("マホマホ王国のプリンセス", 101001, 9, 22, 10, 0, "自警団（カォン）", "マホ", "内田真礼", "O", 42, 155, "空想、ぬいぐるみ集め", 16, "獣人族", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("人懐っこくてマシンガントークな妹系少女", 101101, 8, 25, 3, 0, "ラビリンス", "リノ", "阿澄佳奈", "A", 44, 156, "お裁縫", 15, "ヒューマン", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("みんなのために超能力を使う眠り姫", 101201, 12, 24, 6, 0, "フォレスティエ", "ハツネ", "大橋彩香", "A", 46, 156, "妹と遊ぶこと、二度寝、昼寝、早寝", 17, "エルフ", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("オタク全開な魔法少女", 101301, 8, 21, 13, 0, "トワイライトキャラバン", "ナナカ", "佳村はるか", "O", 55, 166, "読書、魔法", 18, "魔族", "");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("頭脳明晰な美少女名探偵", 101401, 11, 3, 10, 0, "自警団（カォン）", "カスミ", "水瀬いのり", "AB", 41, 152, "読書、推理", 15, "獣人族", "test");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("母性溢れる優しいみんなの「ミサト先生」", 101501, 9, 5, 6, 0, "フォレスティエ", "ミサト", "國府田マリ子", "O", 54, 165, "絵本作り", 21, "エルフ", "test");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("天真爛漫で人気者のカリスマモデル", 101601, 4, 10, 14, 0, "ルーセント学院", "スズナ", "上坂すみれ", "O", 48, 167, "ファッション", 17, "魔族", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("いつでも「なんくるないさ～」な天然娘", 101701, 7, 7, 10, 0, "自警団（カォン）", "カオリ", "高森奈津美", "A", 53, 158, "踊り、空手", 17, "獣人族", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("多くの男性を魅了する無垢な女教師", 101801, 8, 14, 14, 0, "ルーセント学院", "イオ", "伊藤静", "B", 52, 162, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 23, "魔族", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("お歌もにんじんも、ウサギさんも大好き♪", 102001, 4, 3, 5, 0, "リトルリリカル", "ミミ", "日高里菜", "O", 21, 117, "かわいいもの集め", 10, "獣人族", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("泣き虫で臆病な守ってあげたい女の子", 102101, 6, 9, 9, 0, "サレンディア救護院", "クルミ", "植田佳奈", "B", 40, 150, "観劇、おままごと", 12, "ヒューマン", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("人見知りであまのじゃくな女の子", 102201, 11, 22, 7, 0, "悪魔偽王国軍（ディアボロス）", "ヨリ", "原紗友里", "O", 40, 150, "ゲーム全般", 13, "魔族", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("ぷうきちといつも一緒！", 102301, 5, 10, 9, 0, "サレンディア救護院", "アヤネ", "芹澤優", "B", 38, 148, "屋内でできる遊び", 14, "ヒューマン", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("お嬢さまのためにがんばるドジっ娘メイド", 102501, 12, 12, 9, 0, "サレンディア救護院", "スズメ", "悠木碧", "O", 43, 154, "ご奉仕", 15, "ヒューマン", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("遊びと睡眠が何より大事なぐうたら娘", 102601, 1, 1, 11, 0, "牧場（エリザベスパーク）", "リン", "小岩井ことり", "B", 42, 144, "あんパン", 17, "獣人族", "test");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("運命の相手に一途すぎる乙女", 102701, 7, 30, 13, 0, "トワイライトキャラバン", "エリコ", "橋本ちなみ", "B", 43, 154, "実験、裁縫、料理", 16, "魔族", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("救護院を経営する優しい庶民派お嬢様", 102801, 10, 4, 9, 0, "サレンディア救護院", "サレン", "堀江由衣", "A", 43, 156, "経営、お茶会", 17, "エルフ", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("歌って踊れる大人気アイドル", 102901, 1, 24, 4, 0, "カルミナ", "ノゾミ", "日笠陽子", "B", 40, 157, "舞台鑑賞、ダンス", 17, "ヒューマン", "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("トーゴクの神秘、オシエテクダサイ！", 103001, 8, 31, 15, 0, "ヴァイスフリューゲル　ランドソル支部", "ニノン", "佐藤聡美", "O", 51, 163, "忍法開発", 16, "ヒューマン", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("占いが得意な霊能少女", 103101, 12, 22, 7, 0, "悪魔偽王国軍（ディアボロス）", "シノブ", "大坪由佳", "AB", 42, 157, "占い", 18, "魔族", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("一人前の商人を目指すパワフルお嬢様", 103201, 3, 12, 12, 0, "メルクリウス財団", "アキノ", "松嵜麗", "AB", 45, 157, "慈善事業", 18, "ヒューマン", "この私とともにいる限り、\nお金に不自由はさせませんわ！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("みんなを笑顔にするお笑い牧場主", 103301, 3, 3, 11, 0, "牧場（エリザベスパーク）", "マヒル", "新田恵海", "B", 35, 142, "漫才", 20, "ヒューマン", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("純情でほっとけない大人の女性", 103401, 3, 16, 12, 0, "メルクリウス財団", "ユカリ", "今井麻美", "A", 55, 164, "ウインドーショッピング", 22, "エルフ", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("礼儀正しくしっかり者のちびっ子優等生", 103601, 2, 2, 5, 0, "リトルリリカル", "キョウカ", "小倉唯", "A", 21, 118, "お勉強", 8, "エルフ", "test");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("義理堅くてからかい好きな剣術少女", 103701, 8, 11, 8, 0, "王宮騎士団（NIGHTMARE）", "トモ", "茅原実里", "A", 43, 149, "剣術、年長者をからかう", 13, "ヒューマン", "test");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("読書が趣味の病弱少女", 103801, 11, 3, 11, 0, "牧場（エリザベスパーク）", "シオリ", "小清水亜美", "A", 40, 153, "読書、お散歩", 14, "獣人族", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("「友達」に憧れる、エルフの森の女の子", 104001, 6, 6, 6, 0, "フォレスティエ", "アオイ", "花澤香菜", "AB", 44, 158, "友達作りのイメトレ", 13, "エルフ", "友達ができるその日まで…\nBB団で\nトレーニングですっ！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("人々を守るために歌う、唱喚士の少女", 104201, 6, 3, 4, 0, "カルミナ", "チカ", "福原綾香", "O", 46, 163, "各種楽器", 17, "ヒューマン", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("男勝りで情に厚いワイルド娘", 104301, 8, 9, 10, 0, "自警団（カォン）", "マコト", "小松未可子", "O", 54, 168, "お菓子作り", 17, "獣人族", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("かつては夜を支配した最強の吸血鬼", 104401, 5, 5, 7, 0, "悪魔偽王国軍（ディアボロス）", "イリヤ", "丹下桜", "A", 50, 172, "世界征服", "??", "魔族", "test");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("妄想大好き！　ほんとは照れ屋な女の子", 104501, 11, 19, 15, 0, "ヴァイスフリューゲル　ランドソル支部", "クウカ", "長妻樹里", "AB", 49, 157, "小説を読むこと", 18, "ヒューマン", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("弱きを助け強きをくじく猫娘", 104601, 3, 1, 12, 0, "メルクリウス財団", "タマキ", "沼倉愛美", "AB", 48, 158, "猫とたわむれること", 19, "獣人族", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("素顔を見せない冷静沈着な女性騎士", 104701, 10, 25, 8, 0, "王宮騎士団（NIGHTMARE）", "ジュン", "川澄綾子", "A", 50, 171, "格闘技、湯浴み", 25, "ヒューマン", "？？？");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("仕事も私事も効率優先な傭兵少女", 104801, 11, 11, 12, 0, "メルクリウス財団", "ミフユ", "田所あずさ", "O", 49, 163, "傭兵などのアルバイト", 20, "ヒューマン", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("お姉ちゃんがお世話してあげるからねっ！", 104901, 10, 24, 3, 0, "ラビリンス", "シズル", "生天目仁美", "O", 54, 168, "家事全般", 18, "ヒューマン", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("ちょっとおませな恋に恋する女の子", 105001, 1, 3, 14, 0, "ルーセント学院", "ミサキ", "久野美咲", "A", 22, 120, "ファッション誌鑑賞、コスメ集め", 11, "魔族", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("実験が趣味の危険な科学者", 105101, 3, 7, 13, 0, "トワイライトキャラバン", "ミツキ", "三石琴乃", "A", 53, 166, "研究、実験", 27, "ヒューマン", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("乙女チックなもふもふアニマル", 105201, 3, 14, 11, 0, "牧場（エリザベスパーク）", "リマ", "徳井青空", "A", 100, 150, "毛繕い、お喋り", 17, "獣人族", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("見た目も中身もお子ちゃまな異国の軍人", 105301, 7, 28, 15, 0, "ヴァイスフリューゲル　ランドソル支部", "モニカ", "辻あゆみ", "A", 33, 140, "お菓子屋通い", 17, "ヒューマン", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("ファッション大好きなキュートガール", 105401, 9, 7, 4, 0, "カルミナ", "ツムギ", "木戸衣吹", "AB", 45, 153, "裁縫", 14, "ヒューマン", "test");
