INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("人情味溢れる粋でいなせな「姉御」", 105601, 7, 11, 13, 0, "トワイライトキャラバン", "ルカ", "佐藤利奈", "B", 54, 167, "釣り", 25, "ヒューマン", "test");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("空への冒険を夢見る騎空士の少女", 105701, 3, 10, "", 0, "？？？", "ジータ", "金元寿子", "O", 45, 156, "冒険、おしゃべり", 17, "ヒューマン", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("いつも元気な腹ペコ少女", 105801, 3, 31, 1, 0, "美食殿", "ペコリーヌ", "M・A・O", "O", 46, 156, "食べ歩き、料理", 17, "ヒューマン", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("主を慕う、小さなガイド役", 105901, 5, 11, 1, 0, "美食殿", "コッコロ", "伊藤美来", "B", 35, 140, "瞑想、動植物の飼育", 11, "エルフ", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("行き倒れの謎のネコミミ魔法使い", 106001, 9, 2, 1, 0, "美食殿", "キャル", "立花理香", "A", 39, 152, "猫と遊ぶ", 14, "獣人族", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！");
