INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("いつも元気な腹ペコ少女", 107501, 3, 31, 1, 0, "美食殿", "ペコリーヌ（サマー）", "M・A・O", "O", 46, 156, "食べ歩き、料理", 17, "ヒューマン", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("主を慕う、小さなガイド役", 107601, 5, 11, 1, 0, "美食殿", "コッコロ（サマー）", "伊藤美来", "B", 35, 140, "瞑想、動植物の飼育", 11, "エルフ", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("お嬢さまのためにがんばるドジっ娘メイド", 107701, 12, 12, 9, 0, "サレンディア救護院", "スズメ（サマー）", "悠木碧", "O", 43, 154, "ご奉仕", 15, "ヒューマン", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("行き倒れの謎のネコミミ魔法使い", 107801, 9, 2, 1, 0, "美食殿", "キャル（サマー）", "立花理香", "A", 39, 152, "猫と遊ぶ", 14, "獣人族", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("弱きを助け強きをくじく猫娘", 107901, 3, 1, 12, 0, "メルクリウス財団", "タマキ（サマー）", "沼倉愛美", "AB", 48, 158, "猫とたわむれること", 19, "獣人族", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("仕事も私事も効率優先な傭兵少女", 108001, 11, 11, 12, 0, "メルクリウス財団", "ミフユ（サマー）", "田所あずさ", "O", 49, 163, "傭兵などのアルバイト", 20, "ヒューマン", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("占いが得意な霊能少女", 108101, 12, 22, 7, 0, "悪魔偽王国軍（ディアボロス）", "シノブ（ハロウィン）", "大坪由佳", "AB", 42, 157, "占い", 18, "魔族", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("プリン大好きゴースト娘", 108201, 1, 23, 7, 0, "悪魔偽王国軍（ディアボロス）", "ミヤコ（ハロウィン）", "雨宮天", "B", 32, 130, "プリンを食べること", 14, "魔族", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("ちょっとおませな恋に恋する女の子", 108301, 1, 3, 14, 0, "ルーセント学院", "ミサキ（ハロウィン）", "久野美咲", "A", 22, 120, "ファッション誌鑑賞、コスメ集め", 11, "魔族", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("人々を守るために歌う、唱喚士の少女", 108401, 6, 3, 4, 0, "カルミナ", "チカ（クリスマス）", "福原綾香", "O", 46, 163, "各種楽器", 17, "ヒューマン", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("泣き虫で臆病な守ってあげたい女の子", 108501, 6, 9, 9, 0, "サレンディア救護院", "クルミ（クリスマス）", "植田佳奈", "B", 40, 150, "観劇、おままごと", 12, "ヒューマン", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("ぷうきちといつも一緒！", 108601, 5, 10, 9, 0, "サレンディア救護院", "アヤネ（クリスマス）", "芹澤優", "B", 38, 148, "屋内でできる遊び", 14, "ヒューマン", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("人助けが大好き！　前向き格闘娘", 108701, 8, 27, 2, 0, "トゥインクルウィッシュ", "ヒヨリ（ニューイヤー）", "東山奈央", "A", 44, 155, "人助け、応援", 16, "獣人族", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("戦闘のサポートが得意な、心優しい少女", 108801, 4, 5, 2, 0, "トゥインクルウィッシュ", "ユイ（ニューイヤー）", "種田梨沙", "O", 47, 158, "料理、人間観察", 17, "ヒューマン", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("クールで何事にも真っ直ぐな剣士", 108901, 1, 12, 2, 0, "トゥインクルウィッシュ", "レイ（ニューイヤー）", "早見沙織", "B", 46, 163, "読書、乗馬、お茶", 18, "魔族", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("運命の相手に一途すぎる乙女", 109001, 7, 30, 13, 0, "トワイライトキャラバン", "エリコ（バレンタイン）", "橋本ちなみ", "B", 43, 154, "実験、裁縫、料理", 16, "魔族", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("お姉ちゃんがお世話してあげるからねっ！", 109101, 10, 24, 3, 0, "ラビリンス", "シズル（バレンタイン）", "生天目仁美", "O", 54, 168, "家事全般", 18, "ヒューマン", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("英霊と契約を結んだマナリアの天才王女", 109201, 12, 1, "", 0, "？？？", "アン", "日笠陽子", "AB", 55, 156, "読書", 17, "ヒューマン", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("マナリア魔法学院の新入生", 109301, 2, 4, "", 0, "？？？", "ルゥ", "こやまきみこ", "O", 45, 144, "食べること、眠ること", 16, "ヒューマン", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("人を超越した力を有す心優しい竜姫", 109401, 11, 3, "", 0, "？？？", "グレア", "福原綾香", "B", 67, 167, "ピアノ", 17, "半人半竜", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("妄想大好き！　ほんとは照れ屋な女の子", 109501, 11, 19, 15, 0, "ヴァイスフリューゲル　ランドソル支部", "クウカ（オーエド）", "長妻樹里", "AB", 49, 157, "小説を読むこと", 18, "ヒューマン", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("トーゴクの神秘、オシエテクダサイ！", 109601, 8, 31, 15, 0, "ヴァイスフリューゲル　ランドソル支部", "ニノン（オーエド）", "佐藤聡美", "O", 51, 163, "忍法開発", 16, "ヒューマン", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("鬼がかりの万能妹メイド", 109701, 2, 2, "", 0, "？？？", "レム", "水瀬いのり", "?", "??", 154, "演劇鑑賞、詩文", 17, "鬼族", "");
