INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("救護院を経営する優しい庶民派お嬢様", 114501, 10, 4, 9, 0, "サレンディア救護院", "サレン（クリスマス）", "堀江由衣", "A", 43, 156, "経営、お茶会", 17, "エルフ", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！");
