INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("主を慕う、小さなガイド役", 115501, 5, 11, 1, 0, "美食殿", "コッコロ（儀装束）", "伊藤美来", "B", 35, 140, "瞑想、動植物の飼育", 11, "エルフ", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("戦闘のサポートが得意な、心優しい少女", 115601, 4, 5, 2, 0, "トゥインクルウィッシュ", "ユイ（儀装束）", "種田梨沙", "O", 47, 158, "料理、人間観察", 17, "ヒューマン", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("頭脳明晰な美少女名探偵", 115701, 11, 3, 10, 0, "自警団（カォン）", "カスミ（サマー）", "水瀬いのり", "AB", 41, 152, "読書、推理", 15, "獣人族", "");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("乙女チックなもふもふアニマル", 115801, 3, 14, 11, 0, "牧場（エリザベスパーク）", "リマ（シンデレラ）", "徳井青空", "A", 100, 150, "毛繕い、お喋り", 17, "獣人族", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("男勝りで情に厚いワイルド娘", 115901, 8, 9, 10, 0, "自警団（カォン）", "マコト（シンデレラ）", "小松未可子", "O", 54, 168, "お菓子作り", 17, "獣人族", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("マホマホ王国のプリンセス", 116001, 9, 22, 10, 0, "自警団（カォン）", "マホ（シンデレラ）", "内田真礼", "O", 42, 155, "空想、ぬいぐるみ集め", 16, "獣人族", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？");
