INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("弱きを助け強きをくじく猫娘", 116801, 3, 1, 12, 0, "メルクリウス財団", "タマキ（作業服）", "沼倉愛美", "AB", 48, 158, "猫とたわむれること", 19, "獣人族", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("仕事も私事も効率優先な傭兵少女", 116901, 11, 11, 12, 0, "メルクリウス財団", "ミフユ（作業服）", "田所あずさ", "O", 49, 163, "傭兵などのアルバイト", 20, "ヒューマン", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("運命の相手に一途すぎる乙女", 117001, 7, 30, 13, 0, "トワイライトキャラバン", "エリコ（サマー）", "橋本ちなみ", "B", 43, 154, "実験、裁縫、料理", 16, "魔族", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("お姉ちゃんがお世話してあげるからねっ！", 117101, 10, 24, 3, 0, "ラビリンス", "シズル（サマー）", "生天目仁美", "O", 54, 168, "家事全般", 18, "ヒューマン", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("歌って踊れる大人気アイドル", 117201, 1, 24, 4, 0, "カルミナ", "ノゾミ（サマー）", "日笠陽子", "B", 40, 157, "舞台鑑賞、ダンス", 17, "ヒューマン", "");
