INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("実験が趣味の危険な科学者", 117501, 3, 7, 13, 0, "トワイライトキャラバン", "ミツキ（オーエド）", "三石琴乃", "A", 53, 166, "研究、実験", 27, "ヒューマン", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("ボクは誰よりも美しい", 117601, 10, 10, 15, 0, "ヴァイスフリューゲル　ランドソル支部", "ユキ（オーエド）", "大空直美", "AB", 40, 150, "鏡で自分を見ること", 14, "エルフ", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("いつでも「なんくるないさ～」な天然娘", 117701, 7, 7, 10, 0, "自警団（カォン）", "カオリ（ハロウィン）", "高森奈津美", "A", 53, 158, "踊り、空手", 17, "獣人族", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！");
