INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("前世を信じる中二病患者、「疾風の冥姫」", 121901, 7, 5, 13, 0, "トワイライトキャラバン", "アンナ（パイレーツ）", "髙野麻美", "A", 45, 159, "小説執筆", 17, "魔族", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("占いが得意な霊能少女", 122001, 12, 22, 7, 0, "悪魔偽王国軍（ディアボロス）", "シノブ（パイレーツ）", "大坪由佳", "AB", 42, 157, "占い", 18, "魔族", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね");
