INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("人助けが大好き！　前向き格闘娘", 122401, 8, 27, 2, 0, "トゥインクルウィッシュ", "ヒヨリ（サマー）", "東山奈央", "A", 44, 155, "人助け、応援", 16, "獣人族", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？");
