INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("占いが得意な霊能少女", 127101, 12, 22, 7, 0, "悪魔偽王国軍（ディアボロス）", "シノブ（サマー）", "大坪由佳", "AB", 42, 157, "占い", 18, "魔族", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね");
INSERT INTO `v1_bdb790958cf34a91fb2fcbd6ba56479fc7b23a45d7babffba6c8ab4e58f75875` VALUES ("行き倒れの謎のネコミミ魔法使い", 127201, 9, 2, 1, 0, "美食殿", "キャル（編入生）", "立花理香", "A", 39, 152, "猫と遊ぶ", 14, "獣人族", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！");
